package app.metrolife;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;
class FirstDayTests {
 @TempDir Path dir;ObjectMapper m=new ObjectMapper();GameService g;String token;long now=System.currentTimeMillis();
 @BeforeEach void start()throws Exception{g=new GameService(new JsonStore(m,dir.resolve("save.json").toString()),new Content(m),m);g.time=()->now;g.world(null).put("startedAt",now);token=g.guest(null,g.object()).token();}
 ObjectNode input(String name){return g.object().put("username",name).put("pronouns","they").put("city","atl").put("neighborhood","midtown").put("aspiration","founder");}
 ObjectNode sim(){return g.sim(g.session(token,true));}
 void create(){g.setup(token,input("River O'Neil"));}
 void settle(JsonNode started){now=started.path("sim").path("busyUntil").asLong();g.getSim(token);}
 @Test void creatorIsAtomicValidatedAndStartsPoor(){String before=g.me(token).path("user").path("username").asText();for(String bad:new String[]{"A","Room 123","--","Ada_Lee","A".repeat(21),"Ada\u202eLee"})assertThrows(ApiException.class,()->g.setup(token,input(bad)));ObjectNode bad=input("River Stone");bad.set("look",g.object().put("style","party"));assertThrows(ApiException.class,()->g.setup(token,bad));assertEquals(before,g.me(token).path("user").path("username").asText());create();assertEquals(150,sim().path("cash").asInt());assertEquals(35,sim().path("home").path("rent").asInt());assertFalse(sim().path("introDone").asBoolean());assertThrows(ApiException.class,()->g.setup(token,input("Again River")));}
 @Test void introEntersThePrivateStudioAndExitTeachesOutside(){create();g.finishIntro(token);assertEquals("home:"+sim().path("userId").asText(),sim().path("position").path("room").asText());g.finishIntro(token);assertEquals(150,sim().path("cash").asInt());g.door(token,g.object().put("enter",false));assertTrue(sim().path("firstDay").path("outside").asBoolean());assertTrue(sim().path("position").path("room").isNull());}
 @Test void shiftAndMealGoalsAndMoneyWaitForCompletionThenPersist()throws Exception{create();sim().put("loc","techVillage");ActivityFixture.apply(g,token,g.object().put("jobId","tech-1"));assertTrue(sim().path("firstDay").path("job").asBoolean());var shift=ActivityFixture.act(g,token,g.object().put("city","atl").put("loc","techVillage").put("action","shift-tech"));assertFalse(sim().path("firstDay").path("shift").asBoolean());assertEquals(150,sim().path("cash").asInt());settle(shift);assertTrue(sim().path("firstDay").path("shift").asBoolean());var meal=ActivityFixture.act(g,token,g.object().put("city","atl").put("loc","krog").put("action","a0"));assertFalse(sim().path("firstDay").path("meal").asBoolean());g.store.save();now=meal.path("sim").path("busyUntil").asLong();var restored=new GameService(new JsonStore(m,g.store.path.toString()),g.content,m);restored.time=()->now;assertTrue(restored.getSim(token).path("sim").path("firstDay").path("meal").asBoolean());assertTrue(restored.getSim(token).path("sim").path("pendingBeat").isNull());}
 @Test void firstRentCannotDoubleChargeAtNextMidnight(){create();g.finishIntro(token);g.payFirstRent(token);assertEquals(115,sim().path("cash").asInt());assertThrows(ApiException.class,()->g.payFirstRent(token));now=g.civic.dayAt(g.world(null),2)-1000;sim().put("updatedAt",now);now+=2000;g.getSim(token);assertEquals(115,sim().path("cash").asInt());assertTrue(sim().path("firstDay").path("rent").asBoolean());}
 @Test void aPoorWeekAlwaysHasAFreeRecoveryAndPositiveRentMealMargin(){create();g.finishIntro(token);sim().put("cash",0);settle(ActivityFixture.act(g,token,g.object().put("city","atl").put("loc","home").put("action","cook")));assertTrue(sim().path("needs").path("hunger").asDouble()>90);sim().put("loc","techVillage");ActivityFixture.apply(g,token,g.object().put("jobId","tech-1"));for(int day=0;day<7;day++){sim().withObject("needs").put("energy",10);double before=sim().path("cash").asDouble();settle(ActivityFixture.act(g,token,g.object().put("city","atl").put("loc","techVillage").put("action","shift-tech")));assertTrue(sim().path("cash").asDouble()-before>=47);g.property.pay(sim(),47);}assertTrue(sim().path("cash").asDouble()>=0);sim().put("rentDebt",9999).put("cash",20);g.property.rent(sim(),g.world(null),0);assertTrue(sim().path("rentDebt").asInt()<=70);assertEquals(12,sim().path("cash").asInt());}
 @Test void wardrobeAndCityBookingsRespectPoorStart(){create();assertThrows(ApiException.class,()->g.outfit(token,g.object().put("style","work")));g.outfit(token,g.object().put("style","party"));assertEquals(60,sim().path("cash").asInt());g.outfit(token,g.object().put("style","party"));assertEquals(60,sim().path("cash").asInt());assertThrows(ApiException.class,()->g.outfit(token,g.object().put("style","smart")));assertThrows(ApiException.class,()->g.buyPlot(token,g.object().put("city","atl").put("x",0).put("y",0).put("w",1).put("h",1).put("title","My stall")));}
 @Test void migrationBacksUpBeforeDroppingTestWorldsAndKeepsMainLife()throws Exception{create();g.store.data.put("schema",1);g.table("worlds").putObject("test").put("id","test");g.table("sims").putObject("test:test").put("worldId","test");g.user(g.session(token,true)).put("passwordHash","obsolete");g.store.save();byte[] before=Files.readAllBytes(g.store.path);var migrated=new JsonStore(m,g.store.path.toString());assertEquals(2,migrated.data.path("schema").asInt());assertEquals(1,migrated.data.path("worlds").size());assertEquals(1,migrated.data.path("sims").size());assertFalse(migrated.data.path("users").elements().next().has("passwordHash"));try(var paths=Files.list(dir)){Path backup=paths.filter(p->p.getFileName().toString().contains("before-v2")).findFirst().orElseThrow();assertArrayEquals(before,Files.readAllBytes(backup));}var again=new GameService(migrated,g.content,m);assertEquals("River O'Neil",again.me(token).path("sim").path("username").asText());}
 @Test void dayAndNightRotaCannotBeShortenedByAnExtensionPolicy(){var w=g.world(null);g.civic.tick(w);g.civic.state(w,"atl").putObject("mayor").put("policy","nightlife");for(int hour:new int[]{0,3,9,18,23})assertTrue(g.civic.open(w,"atl",g.content.landmark("atl","techVillage"),hour));assertEquals(150,g.content.world.path("startingCash").asInt());}
}
